  "data_catalog": [
    {
      "dataset": "sales_revenue",
      "description": "درآمد فروش به تفکیک مشتری، محصول و ماه",
      "dimensions": [
        "customer",
        "product",
        "month"
      ],
      "measures": [
        "revenue_m_toman",
        "tons",
        "price_per_ton"
      ]
    },
    {
      "dataset": "export_logistics",
      "description": "صادرات: حجم، مقصد، هزینهٔ حمل",
      "dimensions": [
        "destination",
        "month"
      ],
      "measures": [
        "tons",
        "revenue_m_toman",
        "logistics_cost"
      ]
    }
