نقش سازمانی: مدیر انبار و زنجیرهٔ تأمین (warehouse_manager)

درخواست کاربر:
سفارش‌های عقب‌افتاده هفتهٔ گذشته یک‌باره 102 تا شد و مدیر فروش نگران است پوشش ما خراب شده. این جهش چیست؟ (مدیر انبار و زنجیرهٔ تأمین — توزیع قطعات یدکی)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "backorder_log",
      "description": "سفارش‌های عقب‌افتاده به تفکیک روز",
      "dimensions": [
        "date",
        "category"
      ],
      "measures": [
        "orders"
      ]
    },
    {
      "dataset": "supplier_orders",
      "description": "سفارش‌های خرید: تاریخ ثبت، تاریخ تحویل و تأمین‌کننده",
      "dimensions": [
        "supplier",
        "order"
      ],
      "measures": [
        "lead_time_days"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "fill_rate",
      "description": "نرخ پوشش سفارش",
      "formula": "سفارش‌های تکمیل‌شده / کل سفارش‌ها",
      "unit": "درصد",
      "dimensions": [
        "category",
        "period"
      ]
    }
  ],
  "business_context": [
    "شرکت پخش با سه دستهٔ اصلی: پرفروش فصلی، پرفروش ثابت و اقلام مکمل",
    "انبار مرکزی تک‌سایتی؛ تأمین از چند تأمین‌کننده داخلی و یک خارجی"
  ]
}

